import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.Cv-B11KK.js";const h=JSON.parse('{"title":"Release notes","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1790320823000}'),r={name:"changelog.md"};function s(o,e,l,d,c,p){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="release-notes" tabindex="-1">Release notes <a class="header-anchor" href="#release-notes" aria-label="Permalink to &quot;Release notes&quot;">​</a></h1><p>Published releases and downloads are on <a href="https://github.com/LouLouLibs/bbtex/releases" target="_blank" rel="noreferrer">GitHub</a>.</p><h2 id="v0-1-0-first-release" tabindex="-1">v0.1.0: first release <a class="header-anchor" href="#v0-1-0-first-release" aria-label="Permalink to &quot;v0.1.0: first release&quot;">​</a></h2><p><strong>bbtex v0.1.0</strong> is the first release: LaTeX builds, Skim sync, equation previews, a project outline and citation pickers for BBEdit on Apple Silicon. Like everything here, it is totally vibe coded; see <a href="https://louloulibs.github.io/bbtex/about#totally-vibe-coded" target="_blank" rel="noreferrer">About bbtex</a>.</p><p><strong>LaTeX — Toggle Live Selection Preview</strong> makes the reusable preview window follow the BBEdit selection instead of waiting for a save. Delimited math renders as selected; raw text renders as math inside a math selection and as a prose paragraph otherwise. The fragment comes from the live buffer, while the preamble and dependencies still come from saved files. Enabling it turns off Preview on Save, and a full build pauses rendering (&quot;Project busy&quot;) without cancelling it. See <a href="https://louloulibs.github.io/bbtex/selection-preview#live-selection" target="_blank" rel="noreferrer">live selection</a>.</p><p>The persistent <strong>Project Outline Window</strong> adds an expandable searchable tree, automatic saved-source refresh and one window per project. Source jumps retain dirty/stale checks; HTML escaping and a nonce CSP protect displayed TeX text. Doctor now discovers custom package layouts and reports save-hook receipt changes and attachment conflicts. See setup troubleshooting for fresh-machine acceptance.</p><p>BBEdit equation previews now use a compact reusable image window, with cached single-pass rendering for pdfLaTeX, XeLaTeX, and LuaLaTeX. Tectonic is also supported. Full-document PDFs continue to use Skim.</p><p><strong>LaTeX — Project Outline</strong> adds native search across saved project sections, equations, figure/table captions, and labels. Duplicate labels retain their source locations; changed files and unsaved targets require a refreshed outline. The bounded index follows literal includes and reports unavailable inputs. Existing TexLab completion and symbol navigation remain available.</p><p><strong>Insert Citation / Insert Reference</strong> search bibliography metadata or label context and insert keys into the current command. Citation multi-selection, existing options/keys, Undo, cancellation, and changed-buffer checks are supported. Both run in the bbtex binary with no Python dependency: citation search uses the bundled bibtexparser-ml splitter, and reference search uses the shared project index. Both use saved project definitions and reject ambiguous duplicate keys.</p><ul><li>Optional preview on save follows the complete display equation at the cursor.</li><li>Change/Toggle/Close Environment now match nested tags while skipping comments and common literal regions. Rename/toggle are single undoable edits, preserve cursor position, and refuse stale buffers or malformed nesting.</li><li>Wrap in Environment preserves selected lines and indentation, or inserts a paired environment on a blank line. New hyperlink/image clippings provide native argument placeholders. Cancelled or invalid environment clippings preserve selected text.</li><li>Builds recover missing nested include auxiliary directories inside isolated output folders. A new real pdfLaTeX/BibTeX/Biber CI corpus covers article, book, Beamer, previews, diagnostic mapping, and cancellation.</li><li>Real-engine CI now also runs the full corpus under XeLaTeX and LuaLaTeX, including a native Unicode/fontspec fixture and separate diagnostic artifacts.</li><li>Saving a known macro/preamble input refreshes the tracked equation, including background document saves, while preserving editor focus. Changed source locations require a fresh equation save. Recorder-less engines have limited dependency discovery; unsaved buffers remain outside the preview contract.</li><li>The preview shows rendering/current/stale/error/busy status and source context. Previous images are clearly marked out of date; Open Preview Log exposes errors.</li><li>Rapid saves coalesce; superseded previews cancel their own compiler children. Full builds interrupt matching automatic previews and wait for their cleanup. Switching source tabs does not reopen the old preview.</li><li>A BBEdit-only contextual service provides Preview Selection through Services.</li><li>Bundled installers support optional save attachments and the contextual service.</li><li>RaTeX remains an experimental placeholder, with no installation or default change.</li></ul><p>Current releases support Apple Silicon (<code>arm64</code>); Intel artifacts are not currently verified. Extract the ZIP and install <code>bbtex.bbpackage</code>; use the bundled <code>Contents/Resources/selection-preview.md</code> for optional feature setup. Keep either development scripts or the full package installed to avoid duplicate menus. Packages are built and tested on the macOS version of the Mac that ran the release checks; older versions are unverified.</p><p>Preview requires a TeX distribution with <code>preview.sty</code> and Poppler&#39;s <code>pdftoppm</code>. The optional installers are bash and the bbtex binary; they need no Python or uv. Preview-on-save uses saved preambles and dependencies, is off by default, and does not capture unsaved dependency edits.</p>',12)])])}const g=t(r,[["render",s]]);export{h as __pageData,g as default};
